import numpy as np


class FRMIDEPlusV13:
    """Feasibility-rule mixed-integer jDE with success-weighted chronic repair.
    Builds on FRMIDEPlusV11. The chronic-constraint repair now chooses its
    coordinates in proportion to how often past moves on that coordinate reduced
    the chronic constraint, and it only fires on trials whose chronic violation
    is at or below that constraint's running mean (near-miss trials). The
    feasible archive still supplies alternative DE base vectors."""

    def __init__(self, budget=10000, dim=10):
        self.budget = int(budget)
        self.dim = int(dim)

    def __call__(self, func):
        rng = np.random.default_rng(np.random.randint(0, 2**31 - 1))
        d = self.dim
        budget = self.budget

        lb = np.asarray(func.bounds.lb, dtype=float)[:d]
        ub = np.asarray(func.bounds.ub, dtype=float)[:d]
        vt = list(func.variable_types)[:d]
        disc = np.array([t != "continuous" for t in vt])
        cont = ~disc
        catm = np.array([t in ("categorical", "binary") for t in vt])
        ordm = np.array([t == "ordinal" for t in vt])
        nv = np.ones(d, dtype=int)
        for i in range(d):
            if disc[i]:
                nv[i] = int(func.n_values[i])
        ar = np.arange(d)
        m = max(int(getattr(func, "n_constraints", 1)), 0)

        n_eval = 0
        n_feas = 0
        cnt = np.zeros(m)
        vsum = np.zeros(m)
        ema_rate = np.zeros(m)
        tot = [0]
        best = {"f": np.inf, "x": None, "v": np.inf, "xv": None}
        archive = []
        ARCH_MAX = 8
        anc_x = [None] * m
        anc_v = np.full(m, np.inf)
        cw = np.ones(d)  # success counts per variable for chronic repair

        def repair(x):
            x = np.array(x, dtype=float)
            x[cont] = np.clip(x[cont], lb[cont], ub[cont])
            x[disc] = np.clip(np.round(x[disc]), 0, nv[disc] - 1)
            return x

        def score_vec():
            t = max(tot[0], 1)
            rate = 0.5 * cnt / t + 0.5 * ema_rate
            mv = vsum / np.maximum(cnt, 1.0)
            return rate, rate * (mv + 1e-12)

        def hardest():
            _, sc = score_vec()
            return int(np.argmax(sc))

        def chronic():
            return int(np.argmax(ema_rate)) if m > 0 else None

        def weights():
            rate, sc = score_vec()
            emph = sc / (np.max(sc) + 1e-12)
            persist = ema_rate ** 2
            w = 1.0 + 3.0 * rate + 2.0 * emph + 3.0 * persist
            if m > 0:
                w[int(np.argmax(ema_rate))] += 1.0
            return w

        def feas_rate():
            return n_feas / max(n_eval, 1)

        def evaluate(x):
            nonlocal n_eval, n_feas
            n_eval += 1
            f, g = func(x)
            f = float(f)
            if not np.isfinite(f):
                f = np.inf
            g = np.nan_to_num(np.asarray(g, dtype=float).ravel(), nan=1e9, posinf=1e9, neginf=0.0)
            g = np.maximum(g, 0.0)
            if g.shape[0] != m:
                g = np.resize(g, m) if m > 0 else np.zeros(0)
            tot[0] += 1
            if m > 0:
                viol = g > 0
                cnt[:] += viol
                vsum[:] += np.where(viol, g, 0.0)
                ema_rate[:] = 0.97 * ema_rate + 0.03 * viol
                for j in range(m):
                    if g[j] < anc_v[j]:
                        anc_v[j] = g[j]
                        anc_x[j] = np.array(x, copy=True)
            raw = float(np.sum(g))
            feas = (raw <= 0) and np.isfinite(f)
            if feas:
                n_feas += 1
                if f < best["f"]:
                    best["f"], best["x"] = f, np.array(x, copy=True)
                archive.append((f, np.array(x, copy=True)))
                archive.sort(key=lambda t: t[0])
                del archive[ARCH_MAX:]
            elif raw < best["v"]:
                best["v"], best["xv"] = raw, np.array(x, copy=True)
            return f, g

        def key(f, g, w):
            feas = np.isfinite(f) and float(np.sum(g)) <= 0
            if feas:
                return True, f
            val = float(np.dot(w, g)) + (0.0 if np.isfinite(f) else 1.0)
            return False, val

        def better_eq(f1, g1, f2, g2, w):
            a_feas, a = key(f1, g1, w)
            b_feas, b = key(f2, g2, w)
            if a_feas and b_feas:
                return a <= b
            if a_feas:
                return True
            if b_feas:
                return False
            return a <= b

        def is_feas(f, g):
            return np.isfinite(f) and float(np.sum(g)) <= 0

        def vscore(f, g, target):
            s = float(np.sum(g))
            pen = 0.0 if np.isfinite(f) else 1.0
            if target is None or m == 0:
                return s + pen
            return float(g[target]) + 0.1 * s + pen

        def lhs(n):
            X = np.empty((n, d))
            for j in range(d):
                u = (rng.permutation(n) + rng.random(n)) / n
                if disc[j]:
                    X[:, j] = np.floor(u * nv[j])
                else:
                    X[:, j] = lb[j] + u * (ub[j] - lb[j])
            return np.array([repair(x) for x in X])

        def evaluate_population(X, Fv, G):
            for i in range(X.shape[0]):
                if n_eval >= budget:
                    break
                Fv[i], G[i] = evaluate(X[i])

        def coord_repair(x0, max_evals, target=None):
            if n_eval >= budget:
                return
            x = repair(x0)
            fx, gx = evaluate(x)
            used = 1
            cur_v = vscore(fx, gx, target)
            for j in rng.permutation(d):
                if used >= max_evals or n_eval >= budget or is_feas(fx, gx):
                    break
                if disc[j]:
                    if nv[j] <= 1:
                        continue
                    cands = [v for v in range(nv[j]) if v != int(x[j])]
                    if len(cands) > 4:
                        cands = list(rng.choice(cands, 4, replace=False))
                else:
                    span = ub[j] - lb[j]
                    cands = [x[j] + s * span for s in (-0.05, 0.05, -0.2, 0.2)]
                for c in cands:
                    if used >= max_evals or n_eval >= budget:
                        break
                    y = np.array(x, copy=True)
                    y[j] = c
                    y = repair(y)
                    if y[j] == x[j]:
                        continue
                    fy, gy = evaluate(y)
                    used += 1
                    v = vscore(fy, gy, target)
                    if v < cur_v or is_feas(fy, gy):
                        x, fx, gx, cur_v = y, fy, gy, v
                        if is_feas(fx, gx):
                            break

        def multi_seed_repair(X, G, budget_each):
            if best["x"] is not None or m == 0:
                return
            raw = np.array([float(np.sum(G[k])) for k in range(X.shape[0])])
            order = np.argsort(raw)[:3]
            for k in order:
                if n_eval >= budget or best["x"] is not None:
                    break
                tgt = int(np.argmax(G[k])) if G[k].max() > 0 else None
                coord_repair(X[k], budget_each, target=tgt)
            if best["x"] is None and best["xv"] is not None and n_eval < budget:
                coord_repair(best["xv"], budget_each, target=None)

        def chronic_repair(x, fx, gx, c, max_evals):
            # success-weighted coordinate moves that reduce the chronic constraint c
            y_best, f_best, g_best = np.array(x, copy=True), fx, gx
            cur = float(g_best[c]) + 0.1 * float(np.sum(g_best))
            for _ in range(max_evals):
                if n_eval >= budget or float(g_best[c]) <= 0:
                    break
                p = (1.0 + cw) / np.sum(1.0 + cw)
                j = int(rng.choice(d, p=p))
                y = np.array(y_best, copy=True)
                if disc[j]:
                    if nv[j] <= 1:
                        continue
                    y[j] = rng.integers(0, nv[j])
                else:
                    y[j] += rng.normal(0.0, 0.08 * (ub[j] - lb[j]))
                y = repair(y)
                if np.array_equal(y, y_best):
                    continue
                fy, gy = evaluate(y)
                v = float(gy[c]) + 0.1 * float(np.sum(gy))
                if v < cur or is_feas(fy, gy):
                    cw[j] += 1.0
                    y_best, f_best, g_best = y, fy, gy
                    cur = v
                    if is_feas(fy, gy):
                        break
                else:
                    cw[j] = max(1.0, cw[j] * 0.98)
            return y_best, f_best, g_best

        def local_move(xc):
            y = np.array(xc, copy=True)
            k = 1 if rng.random() < 0.7 else 2
            for _ in range(k):
                j = rng.integers(d)
                if disc[j]:
                    if nv[j] > 1:
                        if rng.random() < 0.5:
                            y[j] = np.clip(y[j] + rng.choice([-1, 1]), 0, nv[j] - 1)
                        else:
                            y[j] = rng.integers(0, nv[j])
                else:
                    y[j] += rng.normal(0.0, 0.03 * (ub[j] - lb[j]))
            return repair(y)

        def pick_anchor_constraint(gi, w):
            cands = [j for j in range(m) if gi[j] > 0 and anc_x[j] is not None]
            if not cands:
                return None
            p = np.array([w[j] for j in cands], dtype=float)
            p = p / p.sum()
            return int(cands[rng.choice(len(cands), p=p)])

        NP = min(max(12, 4 * d), 100, budget)
        if NP < 5:
            X = lhs(NP)
            for i in range(NP):
                if n_eval >= budget:
                    break
                evaluate(X[i])
            return (best["f"], best["x"]) if best["x"] is not None else (np.inf, best["xv"])

        X = lhs(NP)
        Fv = np.full(NP, np.inf)
        G = np.ones((NP, m))
        evaluate_population(X, Fv, G)

        if best["x"] is None and n_eval < budget:
            multi_seed_repair(X, G, 2 * d + 4)

        F = np.full(NP, 0.5)
        CR = np.full(NP, 0.9)
        stall = 0
        restarts = 0
        stall_limit = 20
        gen = 0

        while n_eval < budget:
            gen += 1
            w = weights()
            b = 0
            for k in range(1, NP):
                if better_eq(Fv[k], G[k], Fv[b], G[b], w):
                    b = k

            gen_start_best = best["f"]
            feasible_known = best["x"] is not None

            if (not feasible_known) and gen % 3 == 0 and n_eval < budget:
                multi_seed_repair(X, G, 2 * d + 4)
                feasible_known = best["x"] is not None

            p_anchor = 0.15 + 0.3 * (1.0 - feas_rate())
            if not feasible_known:
                p_anchor = min(0.7, p_anchor + 0.15)
            p_line = 0.15 if feasible_known else 0.3
            p_local = 0.05 if feasible_known else 0.02
            c_chr = chronic()
            mean_viol = vsum / np.maximum(cnt, 1.0)

            for i in range(NP):
                if n_eval >= budget:
                    break
                Fi = 0.1 + 0.9 * rng.random() if rng.random() < 0.1 else F[i]
                CRi = rng.random() if rng.random() < 0.1 else CR[i]

                if feasible_known and rng.random() < p_local:
                    trial = local_move(best["x"])
                    ft, gt = evaluate(trial)
                    if better_eq(ft, gt, Fv[i], G[i], w):
                        X[i], Fv[i], G[i] = trial, ft, gt
                    continue

                others = np.delete(np.arange(NP), i)
                r1, r2, r3 = rng.choice(others, 3, replace=False)
                xi = X[i]
                xb = X[b]
                if archive and rng.random() < 0.2:
                    xb = archive[rng.integers(len(archive))][1]

                if rng.random() < 0.6:
                    mut = xi + Fi * (xb - xi) + Fi * (X[r1] - X[r2])
                else:
                    mut = X[r1] + Fi * (X[r2] - X[r3])

                mask = rng.random(d) < CRi
                mask[rng.integers(d)] = True
                trial = xi.copy()

                sel = mask & (cont | ordm)
                trial[sel] = mut[sel]

                selc = mask & catm
                if np.any(selc):
                    D = np.stack([xb, X[r1], X[r2]])
                    pick = rng.integers(0, 3, d)
                    trial[selc] = D[pick[selc], ar[selc]]

                rm = rng.random(d) < 1.0 / d
                rmd = rm & disc
                if np.any(rmd):
                    trial[rmd] = rng.integers(0, nv[rmd])
                rmc = rm & cont
                if np.any(rmc):
                    trial[rmc] += rng.normal(0.0, 0.1 * (ub[rmc] - lb[rmc]))

                trial = repair(trial)
                ft, gt = evaluate(trial)

                # chronic repair, only on near-miss trials (chronic violation at or below its mean)
                if (m > 0 and c_chr is not None and n_eval < budget
                        and not is_feas(ft, gt) and gt[c_chr] > 0
                        and gt[c_chr] <= mean_viol[c_chr] + 1e-12
                        and rng.random() < 0.2):
                    trial, ft, gt = chronic_repair(trial, ft, gt, c_chr, 3)

                if better_eq(ft, gt, Fv[i], G[i], w):
                    X[i] = trial
                    Fv[i] = ft
                    G[i] = gt
                    F[i] = Fi
                    CR[i] = CRi

                infeas = not is_feas(ft, gt)

                if n_eval < budget and infeas and rng.random() < p_anchor:
                    h = pick_anchor_constraint(G[i], w)
                    if h is None:
                        h = hardest()
                    if anc_x[h] is not None and G[i][h] > 0:
                        t = rng.uniform(0.4, 1.0)
                        y = repair(X[i] + t * (anc_x[h] - X[i]))
                        fy, gy = evaluate(y)
                        if better_eq(fy, gy, Fv[i], G[i], w):
                            X[i], Fv[i], G[i] = y, fy, gy
                            infeas = not is_feas(fy, gy)

                if n_eval < budget and infeas and rng.random() < p_line:
                    partner = best["x"]
                    if partner is None:
                        h = hardest()
                        partner = anc_x[h] if anc_x[h] is not None else best["xv"]
                    if partner is not None:
                        lo = np.array(partner, copy=True)
                        hi = np.array(trial, copy=True)
                        for _ in range(2):
                            if n_eval >= budget:
                                break
                            mid = repair(0.5 * (lo + hi))
                            fm, gm = evaluate(mid)
                            if is_feas(fm, gm):
                                lo = mid
                            else:
                                hi = mid
                            if better_eq(fm, gm, Fv[i], G[i], w):
                                X[i], Fv[i], G[i] = mid, fm, gm

            if best["f"] < gen_start_best:
                stall = 0
            else:
                stall += 1

            if stall >= stall_limit and n_eval < budget:
                restarts += 1
                stall = 0
                center = best["x"] if best["x"] is not None else X[b]
                if restarts % 2 == 1:
                    Xn = lhs(NP)
                    Xn[0] = center
                else:
                    Xn = np.empty((NP, d))
                    for k in range(NP):
                        xk = np.array(center, copy=True)
                        scale = 0.02 + 0.2 * rng.random()
                        xk[cont] += rng.normal(0.0, scale, cont.sum()) * (ub[cont] - lb[cont])
                        resample = (rng.random(d) < 0.15) & disc
                        if np.any(resample):
                            xk[resample] = rng.integers(0, nv[resample])
                        Xn[k] = xk
                    Xn = np.array([repair(x) for x in Xn])
                X = Xn
                Fv = np.full(NP, np.inf)
                G = np.ones((NP, m))
                F = np.full(NP, 0.5)
                CR = np.full(NP, 0.9)
                evaluate_population(X, Fv, G)

        if best["x"] is not None:
            return best["f"], best["x"]
        return np.inf, best["xv"]
